from __future__ import annotations

from ..extensions import db
from .common import BigIntPK, loads, new_uid, utcnow


class CommunicationEvent(db.Model):
    """Communication / node events: reported by nodes or generated by the server."""
    __tablename__ = "communication_events"
    __table_args__ = (db.Index("ix_comm_events_node_time", "node_id", "occurred_at"),)
    id = db.Column(BigIntPK, primary_key=True, autoincrement=True)
    event_uid = db.Column(db.String(36), unique=True, nullable=False, default=new_uid)
    origin = db.Column(db.String(8), nullable=False, default="node")   # node | server
    node_id = db.Column(db.Integer, db.ForeignKey("nodes.id"), nullable=False)
    node = db.relationship("Node", lazy="joined")
    controller_id = db.Column(db.Integer, db.ForeignKey("controllers.id"), index=True)
    controller = db.relationship("Controller", lazy="joined")
    occurred_at = db.Column(db.DateTime, nullable=False, index=True)
    received_at = db.Column(db.DateTime, nullable=False, default=utcnow)
    event_type = db.Column(db.String(48), nullable=False, index=True)
    severity = db.Column(db.String(16), nullable=False, default="info")
    message = db.Column(db.String(1000), nullable=False, default="")
    details_json = db.Column(db.Text)

    @property
    def details(self) -> dict:
        return loads(self.details_json, {})


class NodeHeartbeat(db.Model):
    __tablename__ = "node_heartbeats"
    __table_args__ = (db.Index("ix_heartbeats_node_time", "node_id", "received_at"),)
    id = db.Column(BigIntPK, primary_key=True, autoincrement=True)
    node_id = db.Column(db.Integer, db.ForeignKey("nodes.id"), nullable=False)
    received_at = db.Column(db.DateTime, nullable=False, default=utcnow)
    node_time = db.Column(db.DateTime)
    uptime_s = db.Column(db.Integer)
    software_version = db.Column(db.String(32))
    config_version = db.Column(db.Integer)
    queue_pending = db.Column(db.Integer)
    upload_failures = db.Column(db.Integer)
    clock_synchronized = db.Column(db.Boolean)
    ip = db.Column(db.String(64))
    summary_json = db.Column(db.Text)

    @property
    def summary(self) -> dict:
        return loads(self.summary_json, {})


class FaultEvent(db.Model):
    """A controller fault/alarm period, derived from transitions in the fault
    status register (40012) and alarm relay bit (40011 bit1) of recorded readings."""
    __tablename__ = "fault_events"
    __table_args__ = (db.Index("ix_fault_events_controller_start", "controller_id", "started_at"),)
    id = db.Column(db.Integer, primary_key=True)
    node_id = db.Column(db.Integer, db.ForeignKey("nodes.id"), nullable=False, index=True)
    controller_id = db.Column(db.Integer, db.ForeignKey("controllers.id"), nullable=False)
    controller = db.relationship("Controller", lazy="joined")
    kind = db.Column(db.String(8), nullable=False, default="fault")   # fault | alarm
    code = db.Column(db.String(48), nullable=False, index=True)
    description = db.Column(db.String(255), nullable=False, default="")
    status = db.Column(db.String(8), nullable=False, default="active", index=True)  # active | cleared
    started_at = db.Column(db.DateTime, nullable=False)
    cleared_at = db.Column(db.DateTime)
    start_reading_uid = db.Column(db.String(36))
    clear_reading_uid = db.Column(db.String(36))
    start_temperature_c = db.Column(db.Float)
